"""GATE 4 — STAGE 1. DECODE AND PERSIST. NO METRICS, NO RANKING.

⛔ THE APPARATUS IS FROZEN. This script READS it and never writes to it. Stage 1
is execution and data production. It is NOT methodology, and a decoder performing
badly is a RESULT, never a reason to reopen the method.

WHAT IT DOES, per admissible arm x per frozen corpus cell:
    source WAV (D:, read-only) -> arm.sr_in -> encode -> decode
      OFFLINE  full-context reconstruction          -> C:
      STREAMED at that arm's frozen E3 condition    -> H:
    then: §8 validity, the frozen length policy, sha256, one manifest row.

⛔ STORAGE SPLIT (owner decision). Offline outputs to C:, streamed to H:. No
single drive holds the measured 36.4 GB. The output LOCATION is storage plumbing,
not an estimand: every row records the ABSOLUTE PATH and the SHA-256, so a
reader reconstructs the tree from the manifest regardless of where it sits.

⛔ WHAT THIS SCRIPT WILL NOT DO
  - compute a metric, a score, a ranking or a comparison        (Stage 2)
  - discard a failed cell                                        (§12)
  - convert a fail-closed STATE into a number                    (R1)
  - change source selection based on decoder performance
  - tune anything against mcd or the support domain
  - touch the `fish` environment beyond READING it

FAIL-CLOSED STATES, recorded verbatim, never numeric:
    LENGTH FAILURE · NOT ADMISSIBLE · BLOCKED - PLATFORM
    NOT COMPARABLE - OUTSIDE VALIDATED SUPPORT   (Stage 2 applies this)
    QUALITY COMPARISON NOT ESTABLISHED           (Stage 2 applies this)

USAGE - one GPU process at a time (§7.4):
    <decbench>/python.exe        gate4_run.py --env decbench
    <decbench_melflow>/python.exe gate4_run.py --env decbench_melflow
    <fish>/python.exe            gate4_run.py --env fish
    ... --smoke     plumbing validation only, writes to a SEPARATE tree tagged
                    NON_STUDY_SMOKE_TEST, never entering any result count.
"""

import argparse
import hashlib
import json
import os
import sys
import time
import traceback

import numpy as np
import soundfile as sf
import torch

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)

import gate3_lib as L3          # noqa: E402  frozen: §8 validity
import gate4_lib as G4          # noqa: E402  frozen: the one resampler
import gate4_length_policy as LP  # noqa: E402  frozen: tolerances from Gate 2

SRC_ROOT = r"<PRIVATE_SOURCE_ROOT>"
OFFLINE_ROOT = r"<PRIVATE_HOME>\Desktop\research\decoder-bench\results\gate4_wavs_offline"
STREAM_ROOT = r"<PRIVATE_STREAMED_ROOT>"
SMOKE_ROOT = r"<PRIVATE_HOME>\Desktop\research\decoder-bench\results\_NON_STUDY_SMOKE_TEST"

SEX = {"Speaker_01": "Female", "Speaker_02": "Female", "Speaker_04": "Female",
       "Speaker_05": "Female", "Speaker_07": "Female", "Speaker_03": "Male", "Speaker_06": "Male"}

ENV_ARMS = {
    "decbench": ["focalcodec_50hz_4k_causal", "focalcodec_50hz_2k_causal",
                 "focalcodec_50hz_65k_causal", "focalcodec_50hz", "focalcodec_25hz",
                 "focalcodec_12_5hz", "mimi_q8", "mimi_q32", "encodec24_q8",
                 "dac44", "dualcodec_12hz_v1", "dualcodec_25hz_v1",
                 "qwen3_tts_tokenizer_12hz", "vocos_mel24", "griffinlim",
                 "bigvgan22", "encodec_vocos"],
    "decbench_melflow": ["melflow"],
    "fish": ["fish_modified_dac"],
}


def sha256_file(p, buf=1 << 20):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for c in iter(lambda: f.read(buf), b""):
            h.update(c)
    return h.hexdigest()


def frozen():
    """Read the frozen apparatus. Never written to."""
    C = json.load(open(os.path.join(HERE, "GATE4_CORPUS.json")))
    g2 = {m["arm"]: m for m in json.load(
        open(os.path.join(HERE, "gate2_matrix.json")))["matrix"]}
    g3 = {a["arm"]: a for a in json.load(
        open(os.path.join(HERE, "gate3_matrix.json")))["arms"]}
    return C, g2, g3


def source_path(rec):
    d = os.path.join(SRC_ROOT, SEX[rec["speaker"]], rec["speaker"], "English",
                     rec["state"])
    return os.path.join(d, rec["file"])


def cells(C):
    """Every Stage 1 cell, from the frozen corpus. Deterministic order."""
    out = []
    for r in C["cells"]["set_S"]:
        out.append({**r, "set": "S", "rung_s": None})
    rung = C["set_L"]["top_rung_s"]
    ladder = C["set_L"]["duration_ladder_s"]
    lad_idx = set(C["set_L"]["ladder_indices"])
    for r in C["cells"]["set_L"]:
        out.append({**r, "set": "L", "rung_s": rung})
        if r["index"] in lad_idx:
            for x in ladder[:-1]:
                out.append({**r, "set": "L_ladder", "rung_s": x})
    return out


def build_arm(name):
    """The FROZEN adapters. No new per-arm decode path is written (§10)."""
    import gate3_arms as A
    reg = {c.name: c for c in A.DECBENCH_ARMS}
    try:
        import gate3_arms_b as B
        reg.update({c.name: c for c in B.ARMS})
    except Exception:
        pass
    try:
        import gate3_arms_fish as Fi
        reg.update({c.name: c for c in Fi.ARMS})
    except Exception:
        pass
    if name not in reg:
        return None
    return reg[name]()


def write_wav(path, wav, sr):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    x = wav.detach().float().cpu().numpy().reshape(-1)
    sf.write(path, x, int(sr), subtype="FLOAT")
    return x.size


def _record(manifest, row):
    """SECTION 12: every state is a RECORDED ROW. The smoke test caught this
    being violated - BLOCKED and NOT ADMISSIBLE rows were built and dropped."""
    manifest.write(json.dumps(row) + "\n")
    manifest.flush()
    return [row], 0, 0


#: Arms with no Stage 1 adapter, and the exact reason. FAIL CLOSED - no decode
#: path is invented during execution.
NO_ADAPTER = {
    "melflow": (
        "NOT ADMISSIBLE - STAGE 1 ADAPTER NOT ESTABLISHED",
        "No class adapter exists in gate3_arms*. This arm's frozen decode path "
        "lives in gate3_run_melflow.py, whose features() calls A.probe(seconds) "
        "and is HARD-WIRED TO THE FROZEN 15.86 s PROBE. Driving it from arbitrary "
        "corpus files means rewriting the decode path of an AGPL-isolated arm "
        "carrying two declared upstream repairs to ab2700c1 - engineering with "
        "its own design, not wiring, and NOT invented during a frozen execution "
        "phase. Its source-referenced cells were ALREADY NOT ADMISSIBLE (F4: no "
        "samples_per_unit in frozen Gate 2, hence no length tolerance). Its "
        "tier-A self-referential work remains possible once an adapter is "
        "declared and reviewed."),
}


def run_arm(arm_name, C, g2, g3, dev, smoke, limit, manifest, done):
    m2, m3 = g2.get(arm_name), g3.get(arm_name)
    if m3 is None or str(m3.get("status", "")).startswith("BLOCKED"):
        return _record(manifest, {
            "arm": arm_name, "status": "BLOCKED", "smoke": bool(smoke),
            "state_label": "BLOCKED - PLATFORM",
            "note": "released tooling not runnable in this Windows-native "
                    "environment; no number is manufactured, in any format"})
    if arm_name in NO_ADAPTER:
        lab, why = NO_ADAPTER[arm_name]
        return _record(manifest, {
            "arm": arm_name, "status": "NOT ADMISSIBLE", "smoke": bool(smoke),
            "state_label": lab, "note": why})

    rows = []
    arm = build_arm(arm_name)
    if arm is None:
        return _record(manifest, {
            "arm": arm_name, "status": "NOT ADMISSIBLE", "smoke": bool(smoke),
            "state_label": "NOT ADMISSIBLE - NO ADAPTER IN THIS ENVIRONMENT",
            "note": "build_arm() found no frozen adapter for this arm here"})

    e3 = m3.get("e3_min_viable_streaming_ms")
    e3_units = None
    if isinstance(e3, (int, float)):
        for srow in (m3.get("stream") or []):
            if abs(srow["effective_ms"] - e3) < 1e-6:
                e3_units = srow["chunk_units"]
    stateful = bool(getattr(arm, "state_constructible", False))
    off_tol, off_why = LP.offline_tolerance(arm_name)

    t0 = time.time()
    arm.load(dev)
    todo = cells(C)
    if limit:
        todo = todo[:limit]
    ok = fail = 0
    root_off = os.path.join(SMOKE_ROOT if smoke else OFFLINE_ROOT, arm_name)
    root_str = os.path.join(SMOKE_ROOT if smoke else STREAM_ROOT, arm_name)

    for i, cell in enumerate(todo):
        key = "%s|%s|%s|%s|%s|%s" % (arm_name, cell["set"], cell["speaker"],
                                     cell["state"], cell["index"], cell["rung_s"])
        if key in done:
            continue
        stem = "%s_%s_%04d%s" % (cell["speaker"], cell["state"], cell["index"],
                                 ("" if cell["rung_s"] is None
                                  else "_%gs" % cell["rung_s"]))
        row = {"arm": arm_name, "key": key, "set": cell["set"],
               "speaker": cell["speaker"], "sex": cell["sex"],
               "state": cell["state"], "index": cell["index"],
               "rung_s": cell["rung_s"], "source_file": cell["file"],
               "source_sha256": cell.get("sha256"),
               "sr_in": None, "sr_out": int(m2["sr_out"]),
               "e3_ms": e3 if isinstance(e3, (int, float)) else str(e3),
               "stateful_stream": stateful,
               "offline_length_tolerance": off_tol,
               "smoke": bool(smoke)}
        if smoke:
            row["study_status"] = "NON_STUDY_SMOKE_TEST"
        try:
            src, sr0 = sf.read(source_path(cell), dtype="float64", always_2d=True)
            src = src.mean(axis=1)
            if cell["rung_s"]:
                src = src[:int(round(cell["rung_s"] * sr0))]
            row["source_seconds"] = float(src.size / sr0)

            sr_in = int(getattr(arm, "sr_in", m2["sr_out"]))
            row["sr_in"] = sr_in
            x, prov = G4.resample(src, sr0, sr_in)
            row["resampler"] = prov
            wav = torch.from_numpy(np.ascontiguousarray(x)).float().reshape(1, -1).to(dev)

            rep = arm.encode(wav)                      # never inside a timed region
            n_units = arm.n_units(rep)
            row["n_units"] = int(n_units)

            out = arm.decode(rep).reshape(1, -1)
            exp_s = n_units * arm.samples_per_unit / arm.sr_out
            vc, verdict = L3.validity(out, arm.sr_out, exp_s,
                                      frame_s=arm.samples_per_unit / arm.sr_out)
            row["offline_gate8"] = verdict
            row["offline_gate8_failing"] = [k for k in
                                            ("channels_ok", "dtype_ok", "finite",
                                             "peak_in_range", "duration_ok")
                                            if not vc.get(k, True)]
            row["offline_samples"] = int(out.shape[-1])
            row["offline_expected_samples"] = int(round(exp_s * arm.sr_out))
            row["offline_length_delta"] = (row["offline_samples"]
                                           - row["offline_expected_samples"])
            if off_tol is None:
                row["offline_length_state"] = "NOT ESTABLISHED"
            elif abs(row["offline_length_delta"]) > off_tol:
                row["offline_length_state"] = "LENGTH FAILURE"
            else:
                row["offline_length_state"] = "OK"

            p_off = os.path.join(root_off, cell["set"], stem + "__offline.wav")
            write_wav(p_off, out, arm.sr_out)
            row["offline_path"] = os.path.abspath(p_off)
            row["offline_sha256"] = sha256_file(p_off)
            row["offline_bytes"] = os.path.getsize(p_off)

            if e3_units:
                st = arm.new_state() if stateful else None
                parts, seams = [], []
                nch = int(n_units) // int(e3_units)
                for k in range(nch):
                    sl = arm.slice(rep, k * e3_units, e3_units)
                    if stateful:
                        o, st = arm.decode_stateful(sl, st)
                    else:
                        o = arm.decode(sl)
                    o = o.reshape(1, -1)
                    if parts:
                        seams.append(sum(p.shape[-1] for p in parts))
                    parts.append(o)
                if parts:
                    so = torch.cat(parts, dim=-1)
                    sv, sverdict = L3.validity(
                        so, arm.sr_out, nch * e3_units * arm.samples_per_unit / arm.sr_out,
                        frame_s=arm.samples_per_unit / arm.sr_out)
                    row["streamed_gate8"] = sverdict
                    row["streamed_chunks"] = nch
                    row["streamed_chunk_units"] = int(e3_units)
                    row["streamed_samples"] = int(so.shape[-1])
                    row["streamed_seams"] = len(seams)
                    p_str = os.path.join(root_str, cell["set"], stem + "__streamed.wav")
                    write_wav(p_str, so, arm.sr_out)
                    row["streamed_path"] = os.path.abspath(p_str)
                    row["streamed_sha256"] = sha256_file(p_str)
                    row["streamed_bytes"] = os.path.getsize(p_str)
                    row["seam_indices"] = seams
            else:
                row["streamed_state"] = ("NOT ACHIEVABLE" if e3 == "NOT ACHIEVABLE"
                                         else str(e3))
            row["status"] = "OK"
            ok += 1
        except Exception as e:
            row["status"] = "FAILED"
            row["error"] = "%s: %s" % (type(e).__name__, e)
            row["traceback"] = traceback.format_exc()[-1200:]
            fail += 1          # §12: a failure is a RECORDED ROW, never a missing one
        rows.append(row)
        manifest.write(json.dumps(row) + "\n")
        manifest.flush()
        if (i + 1) % 100 == 0:
            print("    %s %d/%d  ok=%d fail=%d  %.0fs"
                  % (arm_name, i + 1, len(todo), ok, fail, time.time() - t0),
                  flush=True)
    arm.unload()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    print("  %-28s ok=%-5d fail=%-4d  %.0fs" % (arm_name, ok, fail, time.time() - t0),
          flush=True)
    return rows, ok, fail


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--env", required=True)
    ap.add_argument("--smoke", action="store_true")
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--arms", default="")
    a = ap.parse_args()

    C, g2, g3 = frozen()
    arms = [x for x in a.arms.split(",") if x] or ENV_ARMS.get(a.env, [])
    dev = "cuda" if torch.cuda.is_available() else "cpu"
    tag = "smoke_" if a.smoke else ""
    out = os.path.join(HERE, "results", "gate4_stage1_%s%s.jsonl" % (tag, a.env))
    os.makedirs(os.path.dirname(out), exist_ok=True)

    # RESUME: a completed scientific cell is never re-run, duplicated or overwritten.
    done = set()
    if os.path.isfile(out):
        for line in open(out):
            try:
                r = json.loads(line)
            except Exception:
                continue
            if r.get("status") == "OK" and r.get("key"):
                done.add(r["key"])
    print("env=%s device=%s arms=%d  already-complete cells=%d%s"
          % (a.env, dev, len(arms), len(done),
             "   [NON_STUDY_SMOKE_TEST]" if a.smoke else ""), flush=True)

    tot_ok = tot_fail = 0
    with open(out, "a") as mf:
        for name in arms:
            _, ok, fail = run_arm(name, C, g2, g3, dev, a.smoke, a.limit, mf, done)
            tot_ok += ok
            tot_fail += fail
    print("\nENV %s COMPLETE  ok=%d failed=%d  manifest=%s"
          % (a.env, tot_ok, tot_fail, out), flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main())
